@implements IDisposable
@inject IAddressValidator AddressValidator

<fieldset disabled="@_validating">
    <div class="mb-3">
        <label for="name">Name</label>
        <input id="name" class="form-control" @bind="Shipping.Name" />
    </div>

    <div class="mb-3">
        <label for="address">Address</label>
        <input id="address" class="form-control" @bind="Shipping.Address" />
    </div>

    <div class="mb-3">
        <label for="city">City</label>
        <input id="city" class="form-control" @bind="Shipping.City" />
    </div>

    <div class="mb-3">
        <label for="zip">Zip Code</label>
        <input id="zip" class="form-control" @bind="Shipping.ZipCode" />
    </div>
</fieldset>

@if (!string.IsNullOrEmpty(_error))
{
    <div class="alert alert-danger" role="alert">@_error</div>
}

<button class="btn btn-primary"
        disabled="@_validating"
        @onclick="ValidateAndProceed">
    @if (_validating)
    {
        <span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
        <span>Validating…</span>
    }
    else
    {
        <span>Next</span>
    }
</button>

@code {
    private CancellationTokenSource? _cts;
    private bool _validating;
    private string? _error;

    [Parameter, EditorRequired]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private async Task ValidateAndProceed()
    {
        _error = null;

        // Cancel any in-flight validation (user changed fields and clicked Next again).
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _validating = true;

        try
        {
            var valid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, token);

            token.ThrowIfCancellationRequested();

            if (valid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _error = "The address could not be verified. Please check your details.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was superseded or component disposed — nothing to do.
        }
        finally
        {
            _validating = false;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

